args.new_string:
// Async server component for per-request user data — no 'use cache' since this
// data is user-specific and must be fetched fresh on every request.
// The parent page wraps this in <Suspense> so it streams at request time.
export default async function UserDashboard() {
  const res = await fetch('https://localhost:3000/api/user/preferences', {
    cache: 'no-store',
  });
  const preferences = await res.json();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>Theme: {preferences.theme}</p>
      <p>Language: {preferences.language}</p>
      <p>Notifications: {preferences.notifications ? 'On' : 'Off'}</p>
    </div>
  );
}

